{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dists = case['distances']
    edges = []
    for u, v, d in dists:
        mr = max(core[u], core[v], d)
        edges.append((mr, u, v))
    processed = []
    for mr, u, v in edges:
        if u > v:
            u, v = v, u
        processed.append((mr, u, v))
    processed.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for mr, u, v in processed:
        if len(mst_edges) == len(nodes) - 1:
            break
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("disconnected input")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
